const NIV=["Inicial","Primaria","Secundaria"];
const G=[{n:"Inicial · 4 años",v:"Inicial"},{n:"Inicial · 5 años",v:"Inicial"},...[1,2,3,4,5,6].map(i=>({n:i+"° de Primaria",v:"Primaria"})),...[1,2,3,4,5].map(i=>({n:i+"° de Secundaria",v:"Secundaria"}))];
const $=id=>document.getElementById(id);
const esc=s=>{const d=document.createElement("div");d.textContent=s??"";return d.innerHTML};
const YAPE={num:"991 999 201",titular:"Angela Samantha Taipe Asparrin",qr:"data:image/png;base64,"}; // ← pon aquí el número de Yape, el titular y (opcional) la imagen del QR
const P_DEL=13,P_LIB=15;
let rows=[],libres=[];
async function api(url,body,method){
  const r=await fetch(url,{method:method||"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body),credentials:"same-origin"});
  let j={};try{j=await r.json()}catch(_){}
  if(!r.ok)throw new Error(j.error||("Error "+r.status));
  return j;
}
const BANK={banco:"BCP",cuenta:"19117783511041",cci:"00219111778351104157",titular:"Ángela S. Taipe A.",moneda:"Soles"};
const IC='<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#7a2cff" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-5px;margin-right:8px"><rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10.5 5.5h3"/><path d="M9.5 12.5l2 2 3.5-4"/><circle cx="12" cy="18.6" r=".6" fill="#7a2cff"/></svg>';
function payHTML(k,monto){
  const n=YAPE.num?`<div class="ynum">${IC}${esc(YAPE.num)}</div>${YAPE.titular?`<div style="color:var(--mut)">A nombre de ${esc(YAPE.titular)}</div>`:""}`:`<div class="ynum" style="font-size:16px">Solicita el número de Yape por WhatsApp:<br><a href="https://wa.me/51991999201" style="color:#7a2cff">991 999 201</a></div>`;
  const cp=(t)=>`<button type="button" class="cp" data-t="${t}">Copiar</button>`;
  return `<div style="color:var(--mut)">Total a pagar</div><div class="tot" id="${k}Tot">S/ ${monto}</div>
  <div class="meth" data-k="${k}"><button type="button" class="mt on" data-m="Yape">Yape</button><button type="button" class="mt" data-m="Transferencia">Transferencia bancaria</button></div>
  <div class="mb" data-m="Yape">
    <div class="yape">${YAPE.qr?`<img src="${YAPE.qr}" alt="QR de Yape">`:""}<div>${n}</div></div>
    <ol><li>Abre Yape, escanea el QR o yapea al número y paga el <b>total</b>.</li><li>Copia el <b>N° de operación</b> de tu constancia.</li><li>Escríbelo abajo y envía tu inscripción.</li></ol>
  </div>
  <div class="mb hide" data-m="Transferencia">
    <div class="bank">
      <div><span>Banco</span><b>${BANK.banco} · Cuenta en ${BANK.moneda}</b></div>
      <div><span>N° de cuenta</span><b>${BANK.cuenta}</b>${cp(BANK.cuenta)}</div>
      <div><span>CCI (otros bancos)</span><b>${BANK.cci}</b>${cp(BANK.cci)}</div>
      <div><span>Titular</span><b>${BANK.titular}</b></div>
    </div>
    <ol><li>Transfiere el <b>total</b> desde tu banca móvil (usa el CCI si es de otro banco).</li><li>Copia el <b>N° de operación</b> de la constancia.</li><li>Escríbelo abajo y envía tu inscripción.</li></ol>
  </div>
  <div class="grid"><div><label>N° de operación *</label><input id="${k}Op" inputmode="numeric" maxlength="60" placeholder="Ej. 12345678"><small style="color:var(--mut)">Si pagaste en varias partes, sepáralos con coma.</small></div><div><label>Nombre de quien pagó (obligatorio)</label><input id="${k}Pg" placeholder="Nombre de quien hizo el pago"></div></div>`;
}
$("payDel").innerHTML=payHTML("pd",0);$("payLib").innerHTML=payHTML("pl",P_LIB);
const medio=id=>($(id).querySelector(".mt.on")||{dataset:{m:"Yape"}}).dataset.m;
const splitOps=v=>String(v||"").split(/[,;\s]+/).filter(Boolean);
const opsOk=v=>{const a=splitOps(v);return a.length>0&&a.every(x=>/^\d{6,12}$/.test(x))};
document.addEventListener("click",e=>{
  const t=e.target.closest(".mt");
  if(t){const box=t.closest(".pay");box.querySelectorAll(".mt").forEach(b=>b.classList.toggle("on",b===t));box.querySelectorAll(".mb").forEach(b=>b.classList.toggle("hide",b.dataset.m!==t.dataset.m));return}
  const c=e.target.closest(".cp");
  if(c){const v=c.dataset.t,done=()=>{c.textContent="¡Copiado!";setTimeout(()=>c.textContent="Copiar",1500)};
    try{navigator.clipboard.writeText(v).then(done,()=>fb())}catch(_){fb()}
    function fb(){const ta=document.createElement("textarea");ta.value=v;document.body.appendChild(ta);ta.select();try{document.execCommand("copy");done()}catch(_){}ta.remove()}}
});
$("lgrado").innerHTML='<option value="">Elegir…</option>'+G.map((g,i)=>`<option value="${i}">${g.n}</option>`).join("");
$("lcel").oninput=e=>e.target.value=e.target.value.replace(/\D/g,"");
$("ldni").oninput=e=>e.target.value=e.target.value.replace(/\D/g,"");["pdOp","plOp"].forEach(id=>$(id).oninput=e=>e.target.value=e.target.value.replace(/[^\d,;\s]/g,""));
function setMode(lib){$("vDel").classList.toggle("hide",lib);$("vLib").classList.toggle("hide",!lib);$("mDel").classList.toggle("on",!lib);$("mLib").classList.toggle("on",lib)}
$("mDel").onclick=()=>setMode(false);$("mLib").onclick=()=>setMode(true);
$("ases").innerHTML=NIV.map(n=>`<div class="as" data-n="${n}"><b>${n}</b><input class="an" placeholder="Apellidos y nombres del asesor(a)"><input class="at" inputmode="tel" maxlength="9" placeholder="Teléfono"></div>`).join("");
$("grados").innerHTML=G.map((g,i)=>`<details data-i="${i}"><summary>${g.n}<span class="c">0 / 10</span></summary><div class="in"><div class="list"></div><button type="button" class="btn sec add" style="margin-top:8px">+ Agregar alumno</button></div></details>`).join("");
const digits=e=>e.target.value=e.target.value.replace(/\D/g,"");
["tel"].forEach(id=>$(id).oninput=digits);
document.querySelectorAll(".at").forEach(i=>i.oninput=digits);
function count(){let t=0;document.querySelectorAll("details").forEach(d=>{const n=d.querySelectorAll(".stu").length;d.querySelector(".c").textContent=n+" / 10";d.querySelector(".add").disabled=n>=10;t+=n});$("pdTot").textContent="S/ "+t*P_DEL;window._n=t;$("tot").textContent=t+" alumno"+(t==1?"":"s")+" inscrito"+(t==1?"":"s")}
function addRow(d){
  const list=d.querySelector(".list"),k=list.children.length;if(k>=10)return;
  const g=G[d.dataset.i],cod=g.n.startsWith("5° de Primaria");
  const r=document.createElement("div");r.className="stu";
  r.innerHTML=`<span class="n">${k+1}</span><input class="sd" inputmode="numeric" maxlength="${cod?14:8}" placeholder="${cod?"DNI / Cód. estud.":"DNI"}"><input class="sn" placeholder="Apellidos y nombres"><button type="button" class="x" title="Quitar">×</button>`;
  r.querySelector(".sd").oninput=digits;
  r.querySelector(".x").onclick=()=>{r.remove();[...list.children].forEach((c,j)=>c.querySelector(".n").textContent=j+1);count()};
  list.appendChild(r);count();
}
document.querySelectorAll("details").forEach(d=>d.querySelector(".add").onclick=()=>{addRow(d)});
document.querySelectorAll("details").forEach(d=>d.addEventListener("toggle",()=>{if(d.open&&!d.querySelector(".stu"))addRow(d)}));
function show(t,c){const m=$("msg");m.className="msg "+c;m.textContent=t;m.scrollIntoView({block:"nearest"})}
const mark=(el,b)=>{el.classList.toggle("err",b);return b};
$("send").onclick=async()=>{
  let bad=false,msg="Revisa los campos en rojo.";
  ["ie","director","dir"].forEach(id=>bad=mark($(id),!$(id).value.trim())||bad);
  bad=mark($("tel"),!/^\d{6,9}$/.test($("tel").value))||bad;
  bad=mark($("mail"),!/^\S+@\S+\.\S+$/.test($("mail").value))||bad;
  const tipo=document.querySelector("input[name=tipo]:checked");if(!tipo){bad=true}
  document.querySelector(".radio").style.outline=tipo?"":"2px solid var(--bad)";
  const alumnos=[],seen=new Set(),nivUsados=new Set();
  document.querySelectorAll("details").forEach(d=>{
    const g=G[d.dataset.i];
    d.querySelectorAll(".stu").forEach((r,k)=>{
      const dni=r.querySelector(".sd"),nom=r.querySelector(".sn"),cod=g.n.startsWith("5° de Primaria");
      const okd=cod?/^(\d{8}|\d{14})$/.test(dni.value):/^\d{8}$/.test(dni.value);
      const dup=seen.has(dni.value);seen.add(dni.value);
      if(dup)msg="Hay un DNI repetido.";
      bad=mark(dni,!okd||dup)||mark(nom,!nom.value.trim())||bad;
      alumnos.push({nivel:g.v,grado:g.n,n:k+1,dni:dni.value,nombre:nom.value.trim()});nivUsados.add(g.v);
    });
  });
  const asesores=[];
  document.querySelectorAll(".as").forEach(a=>{
    const n=a.dataset.n,an=a.querySelector(".an"),at=a.querySelector(".at");
    const need=nivUsados.has(n),has=an.value.trim()||at.value;
    if(need||has){bad=mark(an,!an.value.trim())||mark(at,!/^\d{6,9}$/.test(at.value))||bad;asesores.push({nivel:n,nombre:an.value.trim(),tel:at.value})}
    else{mark(an,false);mark(at,false)}
  });
  if(!alumnos.length)return show("Agrega al menos un alumno en algún grado.","bad");
  bad=mark($("pdOp"),!opsOk($("pdOp").value))||bad;
  if(bad)return show(msg+" (DNI de 8 dígitos; cada nivel con alumnos necesita su asesor; falta el N° de operación del pago).","bad");
  const data={ie:$("ie").value.trim(),director:$("director").value.trim(),tipo:tipo.value,dir:$("dir").value.trim(),tel:$("tel").value,mail:$("mail").value.trim(),asesores,alumnos,monto:alumnos.length*P_DEL,operacion:splitOps($("pdOp").value).join(", "),medio:medio("payDel"),pagador:$("pdPg").value.trim(),fecha:new Date().toISOString()};
  try{
    $("send").disabled=true;
    await api("/api/fichas",data);
    show("¡Inscripción enviada! "+data.ie+" con "+alumnos.length+" alumno(s). Pago registrado: S/ "+data.monto+".","ok");$("pdOp").value="";$("pdPg").value="";
    $("f").reset();document.querySelectorAll(".list").forEach(l=>l.innerHTML="");document.querySelectorAll(".as input").forEach(i=>i.value="");document.querySelectorAll("details").forEach(d=>d.open=false);count();
  }catch(e){show("Error al enviar: "+(e.message||e.code),"bad")}
  $("send").disabled=false;
};
$("sendL").onclick=async()=>{
  const m=(t,c)=>{const e=$("msgL");e.className="msg "+c;e.textContent=t};
  let bad=false;
  bad=mark($("ldni"),!/^\d{8}$/.test($("ldni").value))||bad;
  bad=mark($("lgrado"),!$("lgrado").value)||bad;
  bad=mark($("lnom"),!$("lnom").value.trim())||bad;
  bad=mark($("plOp"),!opsOk($("plOp").value))||bad;
  if(bad)return m("Revisa los campos en rojo.","bad");
  const g=G[$("lgrado").value];
  const data={dni:$("ldni").value,grado:g.n,nivel:g.v,nombre:$("lnom").value.trim(),tel:$("lcel").value, monto:P_LIB,operacion:splitOps($("plOp").value).join(", "),medio:medio("payLib"),pagador:$("plPg").value.trim(),fecha:new Date().toISOString()};
  try{$("sendL").disabled=true;await api("/api/libres",data);
    m("¡Inscripción enviada! "+data.nombre+" ("+data.grado+"). Pago registrado: S/ "+P_LIB+".","ok");
    ["ldni","lnom","lcel","plOp","plPg"].forEach(i=>$(i).value="");$("lgrado").value="";
  }catch(e){m("Error al enviar: "+(e.message||e.code),"bad")}
  $("sendL").disabled=false;
};
function opCell(r){const c=r._c;return `<td${splitOps(r.operacion).some(o=>dups[o]>1)?' style="color:var(--bad);font-weight:700" title="N° de operación repetido"':""}>${esc(r.operacion)}${splitOps(r.operacion).some(o=>dups[o]>1)?" ⚠":""}<br><small style="font-weight:400;color:var(--mut)">${esc(r.medio||"Yape")}</small></td><td><label style="font-weight:400;margin:0;cursor:pointer"><input type="checkbox" style="width:auto" data-c="${r._c}" data-id="${r._id}" ${r.verificado?"checked":""}> ${r.verificado?"✓ Verificado":"Pendiente"}</label></td>`}
let dups={};
function render(){
  rows.forEach(r=>r._c="fichas");libres.forEach(r=>r._c="libres");
  dups={};[...rows,...libres].forEach(r=>splitOps(r.operacion).forEach(o=>dups[o]=(dups[o]||0)+1));
  $("kl").textContent=libres.length;$("kr").textContent="S/ "+(rows.reduce((s,r)=>s+(r.monto||0),0)+libres.reduce((s,r)=>s+(r.monto||0),0));
  $("tbl").innerHTML=libres.map(r=>`<tr><td>${esc(r.dni)}</td><td>${esc(r.grado)}</td><td>${esc(r.nombre)}</td><td>${esc(r.tel)}</td><td>S/ ${r.monto||""}</td>${opCell(r)}</tr>`).join("");
  $("kd").textContent=rows.length;$("ke").textContent=rows.reduce((s,r)=>s+r.alumnos.length,0);
  $("tb").innerHTML=rows.map(r=>`<tr><td>${esc(r.ie)}</td><td>${esc(r.tipo)}</td><td>${esc(r.director)}</td><td>${esc(r.tel)}</td><td>${r.alumnos.length}</td><td>S/ ${r.monto||""}</td>${opCell(r)}</tr>`).join("");
}
$("xl").onclick=()=>{window.location="/api/admin/export.xlsx"};
$("lo").onclick=async()=>{try{await api("/api/admin/logout",{})}catch(_){}$("admin").style.display="none";rows=[];libres=[]};
async function loadAdmin(){
  try{
    const r=await fetch("/api/admin/data",{credentials:"same-origin"});
    if(r.status===401){$("admin").style.display="none";return false}
    const j=await r.json();
    rows=j.fichas;libres=j.libres;$("admin").style.display="";render();return true;
  }catch(_){return false}
}
$("admin").addEventListener("change",async e=>{
  const t=e.target;if(!t.dataset||!t.dataset.id)return;
  try{await api("/api/admin/verify",{t:t.dataset.c,id:Number(t.dataset.id),v:t.checked},"PATCH");loadAdmin()}
  catch(err){t.checked=!t.checked;alert("No se pudo actualizar: "+err.message)}
});
$("adm").onclick=async e=>{
  e.preventDefault();
  if(await loadAdmin()){$("admin").scrollIntoView({behavior:"smooth"});return}
  const pw=prompt("Contraseña del organizador");if(!pw)return;
  try{await api("/api/admin/login",{password:pw});await loadAdmin();$("admin").scrollIntoView({behavior:"smooth"})}
  catch(err){alert(err.message)}
};
loadAdmin();setInterval(()=>{if($("admin").style.display!=="none")loadAdmin()},20000);
(function(){const bg=document.getElementById("bg"),cv=document.createElement("canvas");bg.prepend(cv);const x=cv.getContext("2d");
let W,H,P=[];const N=()=>innerWidth<700?34:70;
function size(){const r=devicePixelRatio||1;W=innerWidth;H=innerHeight;cv.width=W*r;cv.height=H*r;x.setTransform(r,0,0,r,0,0);P=Array.from({length:N()},()=>({x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25,r:1+Math.random()*2}))}
function draw(){x.clearRect(0,0,W,H);
for(let i=0;i<P.length;i++){const a=P[i];for(let j=i+1;j<P.length;j++){const b=P[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<150){x.strokeStyle=`rgba(110,200,255,${.28*(1-d/150)})`;x.lineWidth=1;x.beginPath();x.moveTo(a.x,a.y);x.lineTo(b.x,b.y);x.stroke()}}}
for(const a of P){x.shadowColor="#5bd1ff";x.shadowBlur=10;x.fillStyle="#9fe8ff";x.beginPath();x.arc(a.x,a.y,a.r,0,7);x.fill();x.shadowBlur=0}}
function tick(){for(const a of P){a.x+=a.vx;a.y+=a.vy;if(a.x<0||a.x>W)a.vx*=-1;if(a.y<0||a.y>H)a.vy*=-1}draw();requestAnimationFrame(tick)}
size();addEventListener("resize",size);
if(matchMedia("(prefers-reduced-motion:reduce)").matches)draw();else tick();
})();
document.getElementById("logo2").src=document.getElementById("logo").src;
(function(){
  const bg=document.getElementById("bg");if(!bg)return;
  const F=["π","∑","√","∞","∫","Δ","θ","÷","×","≠","≈","x²","n!","√2","2³=8","7×8=56","sin θ","f(x)","π≈3,14","a²+b²=c²","x²+y²=r²","lim x→∞","∫ f(x)dx","1+1=2","∠90°","%"];
  const n=innerWidth<700?16:30;
  for(let i=0;i<n;i++){
    const e=document.createElement("span");e.textContent=F[Math.floor(Math.random()*F.length)];
    e.style.cssText="left:"+(Math.random()*92)+"%;--s:"+(22+Math.random()*48)+"px;--d:"+(14+Math.random()*20)+"s;--t:"+(-Math.random()*34)+"s;--r:"+((Math.random()*200-100)|0)+"deg;--x:"+((Math.random()*160-80)|0)+"px";
    bg.appendChild(e);
  }
})();
